<?php
require_once 'db.php'; require_once 'auth.php';
start_auth_session(); if (!empty($_SESSION['user_id'])) { header('Location: index.php'); exit; }
$errors=[]; $name=trim($_POST['name']??''); $email=trim($_POST['email']??'');
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf($_POST['csrf']??null); $password=$_POST['password']??''; $confirm=$_POST['password_confirmation']??''; if($name==='')$errors[]='Name is required.'; if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.'; if(strlen($password)<8)$errors[]='Password must be at least 8 characters.'; if($password!==$confirm)$errors[]='Passwords do not match.'; if(!$errors){$check=$pdo->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$check->execute([$email]);if($check->fetch())$errors[]='That email is already registered.';} if(!$errors){$stmt=$pdo->prepare('INSERT INTO users (name,email,password) VALUES (?,?,?)');$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);header('Location: login.php?registered=1');exit;}}
?><!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register - Aisu Vault</title><link rel="stylesheet" href="style.css"></head><body><div class="app"><main class="form-page login-page"><section class="form-header"><span class="eyebrow">Aisu Vault</span><h2>Create account</h2><p>Register to manage your records.</p></section><?php if($errors): ?><div class="alert alert-error"><ul><?php foreach($errors as $error): ?><li><?=htmlspecialchars($error)?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" class="form-card login-card"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><div class="form-group"><label for="name">Name</label><input id="name" name="name" value="<?=htmlspecialchars($name)?>" required></div><div class="form-group"><label for="email">Email</label><input id="email" name="email" type="email" value="<?=htmlspecialchars($email)?>" required></div><div class="form-group"><label for="password">Password</label><input id="password" name="password" type="password" minlength="8" required></div><div class="form-group"><label for="password_confirmation">Confirm password</label><input id="password_confirmation" name="password_confirmation" type="password" minlength="8" required></div><button class="button button-primary" type="submit">Create account</button><p class="login-switch">Already registered? <a href="login.php">Sign in</a></p></form></main></div></body></html>
